public class ExamE {
    public static void main(String[] args) {
        int[] a = {4, 2, 7, 1};
        for (int i = 0; i < a.length - 1; i++) {
            for (int j = 0; j < a.length - 1 - i; j++) {
                if (a[j] > a[j + 1]) {
                    int temp = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = temp;
                }
            }
            System.out.println("第 " + (i + 1) + " 轮：" + Arrays.toString(a));
        }
        System.out.println(Arrays.toString(a));
    }
