```java
public class ExamG {
    public static void main(String[] args) {
        int[] a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        int key = 23;
        int low = 0;
        int high = a.length - 1;
        int result = -1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (a[mid] == key) {
                result = mid;
                break;
            } else if (a[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        System.out.println("result = " + result);
    }
}
```

