```java
import java.util.Arrays;

public class SelfTest20 {
    public static void main(String[] args) {
        int[] a = {3, 1, 4, 2};
        for (int i = 1; i < a.length; i++) {
            int key = a[i];
            int j = i - 1;
            while (j >= 0 && a[j] > key) {
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
            System.out.println(Arrays.toString(a));
        }
    }
}
